<body>
  <div id="app"></div>

  <script>
    const fieldConfigs = {
      fullName: {
        id: "fullName",
        name: "fullName",
        label: "Full name",
        type: "text",
        autocomplete: "name",
        required: true
      },
      email: {
        id: "email",
        name: "email",
        label: "Email address",
        type: "email",
        autocomplete: "email",
        required: true
      },
      phone: {
        id: "phone",
        name: "phone",
        label: "Phone number",
        type: "tel",
        autocomplete: "tel",
        inputmode: "tel",
        required: false,
        helperText: "Optional. Enter a number like (555) 123-4567 or +1 555 123 4567."
      }
    };

    function FormField(config) {
      const helperId = config.helperText ? config.id + "-hint" : "";
      const errorId = config.id + "-error";
      const describedBy = [helperId, errorId].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${config.id}">
            ${config.label}${config.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
          </label>
          <div class="input-shell">
            <input
              id="${config.id}"
              name="${config.name}"
              type="${config.type}"
              ${config.autocomplete ? `autocomplete="${config.autocomplete}"` : ""}
              ${config.inputmode ? `inputmode="${config.inputmode}"` : ""}
              ${config.required ? "required" : ""}
              aria-describedby="${describedBy}"
              aria-errormessage="${errorId}"
            >
            ${config.helperText ? `<p class="field-hint" id="${helperId}">${config.helperText}</p>` : ""}
            <p class="field-error" id="${errorId}"></p>
          </div>
        </div>
      `;
    }

    function SupportForm() {
      return `
        <form id="support-form" novalidate>
          <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required fields</p>
          ${FormField(fieldConfigs.fullName)}
          ${FormField(fieldConfigs.email)}
          ${FormField(fieldConfigs.phone)}
          <p class="form-status" id="form-status" role="status"></p>
          <div class="actions">
            <button type="submit">Send support request</button>
          </div>
        </form>
      `;
    }

    function App() {
      return `
        <a class="skip-link" href="#maincontent">Skip to main content</a>
        <div class="page-shell">
          <header class="page-header">
            <div class="header-inner">
              <p class="eyebrow">Support team contact</p>
            </div>
          </header>
          <main id="maincontent" tabindex="-1">
            <section class="content-card" aria-labelledby="support-title">
              <h1 id="support-title">Contact support</h1>
              <p class="lead">Tell us how to reach you and our support team will follow up with the right next step.</p>
              ${SupportForm()}
            </section>
          </main>
        </div>
      `;
    }

    document.getElementById("app").innerHTML = App();

    const form = document.getElementById("support-form");
    const status = document.getElementById("form-status");
    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phonePattern = /^\+?[0-9\s().-]{7,20}$/;

    function setFieldState(input, message) {
      const error = document.getElementById(input.id + "-error");
      const isInvalid = Boolean(message);

      if (isInvalid) {
        input.setAttribute("aria-invalid", "true");
      } else {
        input.removeAttribute("aria-invalid");
      }

      error.textContent = message;
    }

    function validateField(input) {
      const value = input.value.trim();

      if (input.name === "fullName") {
        if (!value) {
          return "Error: Enter your full name.";
        }
      }

      if (input.name === "email") {
        if (!value) {
          return "Error: Enter your email address.";
        }

        if (!emailPattern.test(value)) {
          return "Error: Enter a valid email address like name@example.com.";
        }
      }

      if (input.name === "phone" && value && !phonePattern.test(value)) {
        return "Error: Enter a valid phone number using digits and common separators.";
      }

      return "";
    }

    function validateForm() {
      const fields = Array.from(form.querySelectorAll("input"));
      const invalidFields = [];

      fields.forEach((field) => {
        const message = validateField(field);
        setFieldState(field, message);

        if (message) {
          invalidFields.push(field);
        }
      });

      return invalidFields;
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      status.textContent = "";

      const invalidFields = validateForm();

      if (invalidFields.length > 0) {
        invalidFields[0].focus();
        return;
      }

      status.textContent = "Your support request is ready to send.";
    });

    form.querySelectorAll("input").forEach((input) => {
      input.addEventListener("blur", () => {
        setFieldState(input, validateField(input));
      });

      input.addEventListener("input", () => {
        if (input.getAttribute("aria-invalid") === "true") {
          setFieldState(input, validateField(input));
        }

        if (status.textContent) {
          status.textContent = "";
        }
      });
    });
  </script>
</body>
